107  
108    function recordPluginFailure(row: resourcesModule.PluginStatus, error: unknown): void {
109      //G 启动真的失败才记为失败，错误原文给标准错误排查。
110      const text = textModule.getErrorMessage(error);
111      console.error(`插件 ${row.name} 没挂上：${text}`);
112      row.mounted = false;
113      row.started = false;
114      row.missing = [];
115      row.error = text;
116      if (/Cannot find module/iu.test(text)) {
117        //G health 和教程只给出找不到入口的原因，不带模块系统的绝对路径。
118        row.error = '找不到这个插件（自带名单里没有，也没有对应的入口文件）';
119      }
120    }
121  
122    //M 以真实 fiber 为键。等依赖或超时后继续启动的插件都能更新自己的那一行。
123    app.on('internal/status', (fiber) => {
124      const row = starting.get(fiber);
125      if (row === undefined) return;
126  
127      if (fiber.state === cordis.FiberState.ACTIVE) {
128        starting.delete(fiber);
129        row.mounted = true;
130        row.started = true;
131        row.missing = [];
132        row.error = '';
133        return;
134      }
135      if (fiber.state !== cordis.FiberState.FAILED) return;
136  
137      //M 缺依赖时首轮等待可能早已返回，由状态事件取出随后启动失败的原因。
138      void fiber.await().catch((error: unknown) => {
139        if (!starting.delete(fiber)) return;
140  
141        recordPluginFailure(row, error);
142      });
143    }, { prepend: true });
144  
```

