**行号：L145–L208**

### 代码原文
```ts
145    //==========================================================
146    //M 按配置顺序发起挂载并限时等待
147    //==========================================================
148    for (const entry of entries) {
149      //M 先按配置名找内置插件，也为加载失败的状态记录注入声明。
150      const builtIn = pluginIndex.BUILT_IN[entry.name];
151      const row: resourcesModule.PluginStatus = {
152        name: entry.name,
153        mounted: false,
154        started: false,
155        missing: [],
156        error: '',
157        inject: builtIn?.inject ?? [],
158      };
159      try {
160        let plugin = builtIn;
161        if (plugin === undefined) {
162          //M 内置表查不到才从外部插件文件夹加载入口。
163          const root = app.resources.root;
164          plugin = await loadExternalPlugin(entry.name, root);
165        }
166  
167        //M 等待 Cordis apply。状态监听使用 thenable 后面的原 fiber。
168        row.inject = plugin.inject ?? [];
169        const mounted = app.plugin(plugin, entry.config);
170        const fiber = mounted.ctx.fiber;
171        starting.set(fiber, row);
172  
173        //M 首次等待结束时也可能在等注入。异步失败即使发生在超时之后也照常记账。
174        const finished = fiber.await().then(() => {
175          if (fiber.state === cordis.FiberState.PENDING && row.error === '') {
176            row.mounted = true;
177          }
178          return true;
179        }, (error: unknown) => {
180          if (starting.delete(fiber)) {
181            recordPluginFailure(row, error);
182          }
183          return true;
184        });
185  
186        const timer = new AbortController();
187        const options = { signal: timer.signal };
188        const deadline = timers.setTimeout(pluginMountTimeoutMs, false, options);
189        const waiting = [finished, deadline];
190        try {
191          const inTime = await Promise.race(waiting);
192          if (!inTime && starting.has(fiber)) {
193            //G 到点只结束本次等待。保留 fiber，让它完成后还能发状态和服务通知。
194            const seconds = pluginMountTimeoutMs / 1000;
195            row.mounted = false;
196            row.error = `启动超过 ${String(seconds)} 秒，先挂后面的，它继续在后台起`;
197            console.error(`插件 ${row.name} ${row.error}`);
198          }
199        } finally {
200          timer.abort();
201        }
202      } catch (error) {
203        recordPluginFailure(row, error);
204      }
205      //M 维持配置顺序，每次发起挂载只占一行，供 health 和启动流程读。
206      app.resources.pluginStatus.push(row);
207    }
208  
```

### 解释
- L148：照配置先后一个个来。
- 每项只在 pluginStatus 里占一行（L206），供 health 和教程读。

