234  /**
235   * 从外部插件文件夹加载入口，优先使用 index.ts，再找 index.js。
236   * @param name 外部插件的文件夹路径，相对路径从运行时目录算。
237   * @param root 配置所在的运行时目录。
238   * @returns 这个插件的模块（导出 name、inject、apply）。导出得不对，Cordis 挂它的时候会报错。
239   */
240  async function loadExternalPlugin(name: string, root: string): Promise<pluginIndex.PluginModule> {
241    //M 按运行时目录解析外部路径，保留已有的入口优先级。
242    const dir = path.resolve(root, name);
243    let entry = path.join(dir, 'index.ts');
244    if (!fs.existsSync(entry)) {
245      entry = path.join(dir, 'index.js');
246    }
247  
248    //M 动态 import 认的是网址：路径先转成 file:// 网址，Windows 的盘符路径才不会被当成别的协议。
249    const entryUrl = pathToFileURL(entry).href;
250    const loaded = await import(entryUrl) as pluginIndex.PluginModule & {
251      default?: pluginIndex.PluginModule;
252    };
253  
254    //M 模块有 default 导出就用 default（DSH 的加载器也是这么做的）。
255    return loaded.default ?? loaded;
256  }
257  
258  
```

